window.ScripturaLexicons.BDAG_PART_0008 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagnizo-bdag\" data-source=\"BDAG\" data-search=\"ἁγνίζω hagnizo purificar limpar dedicar tornar puro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνίζω</td><td>Verbo</td><td>purificar; limpar; dedicar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagnismos-bdag\" data-source=\"BDAG\" data-search=\"ἁγνισμός hagnismos purificação cultual moral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνισμός</td><td>Substantivo</td><td>purificação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agnoeo-bdag\" data-source=\"BDAG\" data-search=\"ἀγνοέω agnoeo ignorar não saber desconhecer não reconhecer não compreender pecar involuntariamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγνοέω</td><td>Verbo</td><td>não saber; ignorar; não compreender; agir sem saber</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agnoema-bdag\" data-source=\"BDAG\" data-search=\"ἀγνόημα agnoema pecado ignorância involuntário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγνόημα</td><td>Substantivo</td><td>pecado cometido por ignorância; falta involuntária</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agnoia-bdag\" data-source=\"BDAG\" data-search=\"ἄγνοια agnoia ignorância falta conhecimento discernimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγνοια</td><td>Substantivo</td><td>ignorância; falta de conhecimento; falta de discernimento</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagnos-bdag\" data-source=\"BDAG\" data-search=\"ἁγνός hagnos puro santo casto inocente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνός</td><td>Adjetivo</td><td>puro; santo; casto; inocente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagnotes-bdag\" data-source=\"BDAG\" data-search=\"ἁγνότης hagnotes pureza sinceridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνότης</td><td>Substantivo</td><td>pureza; sinceridade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagnos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἁγνῶς hagnos advérbio puramente sinceramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγνῶς</td><td>Advérbio</td><td>puramente; sinceramente</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agnosia-bdag\" data-source=\"BDAG\" data-search=\"ἀγνωσία agnosia ignorância falta experiência religiosa discernimento espiritual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγνωσία</td><td>Substantivo</td><td>ignorância; falta de discernimento espiritual</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agnostos-bdag\" data-source=\"BDAG\" data-search=\"ἄγνωστος agnostos desconhecido deus desconhecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγνωστος</td><td>Adjetivo</td><td>desconhecido</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agora-bdag\" data-source=\"BDAG\" data-search=\"ἀγορά agora praça mercado foro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγορά</td><td>Substantivo</td><td>praça; mercado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agorazo-bdag\" data-source=\"BDAG\" data-search=\"ἀγοράζω agorazo comprar adquirir resgatar preço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγοράζω</td><td>Verbo</td><td>comprar; adquirir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agoraios-bdag\" data-source=\"BDAG\" data-search=\"ἀγοραῖος agoraios mercado praça populacho dias tribunal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγοραῖος</td><td>Adjetivo/Substantivo</td><td>do mercado; gente da praça; sessão judicial</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agra-bdag\" data-source=\"BDAG\" data-search=\"ἄγρα agra captura pesca apanhado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄγρα</td><td>Substantivo</td><td>captura; pesca; aquilo que é apanhado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrammatos-bdag\" data-source=\"BDAG\" data-search=\"ἀγράμματος agrammatos analfabeto iletrado sem instrução BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγράμματος</td><td>Adjetivo</td><td>iletrado; sem instrução</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agrauleo-bdag\" data-source=\"BDAG\" data-search=\"ἀγραυλέω agrauleo viver ao ar livre campo pastores BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγραυλέω</td><td>Verbo</td><td>viver ao ar livre</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agreuo-bdag\" data-source=\"BDAG\" data-search=\"ἀγρεύω agreuo apanhar capturar surpreender em palavra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγρεύω</td><td>Verbo</td><td>capturar; apanhar de surpresa</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-hagnizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hagnízō⟧</span><span class=\"separator\">·</span><span class=\"greek\">1 aor. ἥγνισα; pf. ptc. ἡγνικώς · pass. 1 aor. impv. ἁγνίσθητι, ptc. ἁγνισθείς; pf. ptc. ἡγνισμένος</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Trágicos, Heródoto e outros; LXX; TestSol C 12:5; Josefo; SibOr 3, 592; Just., <em>D.</em> 86, 6.)\n<span class=\"sense-number\">1.</span> <strong>Purificar/limpar e assim tornar aceitável para uso cultual, purificar.</strong> <strong>a.</strong> Ativo, de lustrações e ritos de expiação (assim nos trágicos; também ChronLind D 74; Plut., <em>Mor.</em> 263e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ πῦρ καθαίρει κ. τὸ ὕδωρ ἁγνίζει\" data-meanings=\"o fogo limpa e a água purifica\">τὸ πῦρ καθαίρει κ. τὸ ὕδωρ ἁγνίζει</span>), dos judeus antes da Páscoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.55\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.55</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 19.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.31.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cr 31.17 s.</a>; Jos., <em>Bell.</em> 6, 425; <em>Ant.</em> 12, 145). <strong>b.</strong> Médio, <strong>purificar-se</strong> (Plut., <em>Mor.</em> 1105b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3.5</a>; Hippol., <em>Ref.</em> 9, 21, 2), das purificações ligadas ao voto nazireu (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 6.3</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.24</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">24.18</a> (compare B-D-F §314).\n<span class=\"sense-number\">2.</span> <strong>Fazer moralmente puro, purificar</strong>, extensão figurada de 1: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καρδίας\" data-meanings=\"corações\">καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ψυχάς\" data-meanings=\"almas\">ψυχάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑαυτόν\" data-meanings=\"a si mesmo\">ἑαυτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3.3</a>. Passivo, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τῇ ἀφέσει τ. ἁμαρτιῶν\" data-meanings=\"purificar-se pelo perdão dos pecados\">ἁ. τῇ ἀφέσει τ. ἁμαρτιῶν</span>, “tornar-se puro pelo perdão dos pecados”, <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 5:1\" data-tooltip-text=\"Epístola de Barnabé 5:1\">B 5:1</span>. Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. ἀπὸ τῶν ἁμαρτιῶν\" data-meanings=\"purificar-se dos pecados\">ἁ. ἀπὸ τῶν ἁμαρτιῶν</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 8:1\" data-tooltip-text=\"Epístola de Barnabé 8:1\">B 8:1</span>.\n<span class=\"sense-number\">3.</span> Médio (com aoristo passivo), <strong>separar-se em dedicação, dedicar-se</strong>, isto é, entregar-se como propiciação, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπὲρ ὑμῶν\" data-meanings=\"por vós\">ὑπὲρ ὑμῶν</span> IEph 8:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνίζεται ὑπὲρ ὑμῶν τὸ ἐμὸν πνεῦμα\" data-meanings=\"meu espírito se dedica por vós\">ἁγνίζεται ὑπὲρ ὑμῶν τὸ ἐμὸν πνεῦμα</span>, ITr 13:3. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. M-M.\n</p></section></article><article id=\"entry-hagnismos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνισμός</h1><div class=\"entry-meta\"><span class=\"greek\">οῦ, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagnismós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Dionys. Hal. 3, 22; Plut., <em>Mor.</em> 418b e outros; SIG 1219, 19.)\n<span class=\"sense-number\">1.</span> <strong>Processo de tornar algo cultualmente aceitável, purificação</strong>, dos costumes de purificação quando se cumpria um voto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν ἡμερῶν τοῦ ἁ.\" data-meanings=\"dos dias da purificação\">τῶν ἡμερῶν τοῦ ἁ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 21.26</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶσαι αἱ ἡμέραι τοῦ ἁ.\" data-meanings=\"todos os dias da purificação\">πᾶσαι αἱ ἡμέραι τοῦ ἁ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 6.5</a>).\n<span class=\"sense-number\">2.</span> <strong>Processo de ser moralmente purificado, purificação</strong>, extensão figurada de 1 (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνίζω\" data-meanings=\"purificar\">ἁγνίζω</span> 2): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἁ. τῆς καρδίας\" data-meanings=\"a purificação do coração\">ὁ ἁ. τῆς καρδίας</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 8:3\" data-tooltip-text=\"Epístola de Barnabé 8:3\">B 8:3</span>, com perdão de pecados. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. M-M. TW.\n</p></section></article><article id=\"entry-agnoeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγνοέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agnoéō⟧</span><span class=\"separator\">·</span><span class=\"greek\">impf. ἠγνόουν; 1 aor. ἠγνόησα; pf. ἠγνόηκα · pass. fut. ἀγνοηθήσεται; plpf. ἠγνόητο</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγνόηκα\" data-meanings=\"perfeito de ἀγνοέω\">ἠγνόηκα</span> LXX; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγνοηκώς\" data-meanings=\"tendo ignorado; não tendo sabido\">ἠγνοηκώς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/3MA.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">3 Mc 3.9</a>; pass. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοηθήσεται\" data-meanings=\"será ignorado/desconhecido\">ἀγνοηθήσεται</span> Ath., <em>R.</em> 50, 34; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγνόητο\" data-meanings=\"era desconhecido\">ἠγνόητο</span> Ath., <em>R.</em> 50, 30. Sobre a história filológica, veja F. Lindemann, SymbOsl 38, 1963, 69–75. (Homero+.)\n<span class=\"sense-number\">1.</span> <strong>Não estar informado sobre, não saber, ignorar.</strong> <strong>a.</strong> Com oração de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"que\">ὅτι</span> (Περὶ ὕψους 33, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδὲ ἐκεῖνο ἀγνοῶ ὅτι\" data-meanings=\"nem deixo de reconhecer isto: que…\">οὐδὲ ἐκεῖνο ἀγνοῶ ὅτι</span>; PGiss 11, 17 [118 d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">6.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">7.1</a>; MPol 17:2. Fórmula favorita de Paulo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ θέλω ὑμᾶς ἀγνοεῖν\" data-meanings=\"não quero que ignoreis; quero que saibais\">οὐ θέλω ὑμᾶς ἀγνοεῖν</span> (compare Theophr., <em>CP</em> 2, 4, 8; 3, 9, 5; PTebt 314, 3; Fílon, <em>Opif. M.</em> 87; Jos., <em>Ant.</em> 13, 354) “quero que saibais”, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"que\">ὅτι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 10.1</a>; compare 2 Cl 14:2; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περί τινος\" data-meanings=\"acerca de algo\">περί τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 12.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 4.13</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπέρ τινος\" data-meanings=\"acerca de algo/alguém\">ὑπέρ τινος</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι\" data-meanings=\"que\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 1.8</a>; com acusativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.25</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ γὰρ αὐτοῦ τὰ νοήματα ἀγνοοῦμεν\" data-meanings=\"não ignoramos os seus desígnios\">οὐ γὰρ αὐτοῦ τὰ νοήματα ἀγνοοῦμεν</span>, “estamos bem cientes dos desígnios de Satanás”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 2.11</a> (compare Diod S 3, 66, 4; Appian, <em>Samn.</em> 4 §14; Athen. 4, 73, 172f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 12.10</a>; Jos., <em>Bell.</em> 1, 608; <em>Ant.</em> 6, 253; 7, 217; PGM 7, 245). Com pergunta indireta, 2 Cl 10:4; MPol 10:1. Absoluto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοῶν ἐποίησα\" data-meanings=\"fiz ignorando; fiz por ignorância\">ἀγνοῶν ἐποίησα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 1.13</a> (TestJud 12:5; veja 4 abaixo).\n<strong>b.</strong> <strong>Não conhecer</strong>, com acusativo de pessoa (PGiss 69, 4; PPetr III, 53n, 4; Herm. Wr. 11, 21b) ou coisa (SIG 336, 9; 881, 3–4; Mitt-Wilck. I/2, 57, 6 [séc. II a.C.]; Jos., <em>Vi.</em> 107): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῦτον ἀγνοήσαντες\" data-meanings=\"não reconhecendo este\">τοῦτον ἀγνοήσαντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.27</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν τοῦ θεοῦ δικαιοσύνην\" data-meanings=\"a justiça de Deus\">τὴν τοῦ θεοῦ δικαιοσύνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.3</a> (aqui talvez = “desconsiderar”; veja 2 abaixo); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παράπτωμα\" data-meanings=\"transgressão\">παράπτωμα</span> Hm 9:7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ χάρισμα\" data-meanings=\"o dom\">τὸ χάρισμα</span> IEph 17:2; compare MPol 11:2. Absoluto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅ ἀγνοοῦντες εὐσεβεῖτε\" data-meanings=\"aquilo que venerais sem conhecer\">ὅ ἀγνοοῦντες εὐσεβεῖτε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.23</a>; compare ISm 5:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀγνοῶν\" data-meanings=\"aquele que não sabe\">ὁ ἀγνοῶν</span> ITr 6:2. Passivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοοῦνται\" data-meanings=\"são desconhecidos\">ἀγνοοῦνται</span> (os cristãos), Dg 5:12; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοούμενοι\" data-meanings=\"desconhecidos\">ἀγνοούμενοι</span> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιγινωσκόμενοι\" data-meanings=\"conhecidos\">ἐπιγινωσκόμενοι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 6.9</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοούμενος τῷ προσώπῳ ταῖς ἐκκλησίαις\" data-meanings=\"desconhecido pessoalmente às igrejas\">ἀγνοούμενος τῷ προσώπῳ ταῖς ἐκκλησίαις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.22</a> (dativo de relação, B-D-F §197; de maneira, Rob. 530).\n<span class=\"sense-number\">2.</span> <strong>Dar pouca ou nenhuma atenção, não reconhecer, desconsiderar, ignorar</strong> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10.3</a> acima): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἴ τις ἀγνοεῖ, ἀγνοεῖται\" data-meanings=\"se alguém ignora, é ignorado\">εἴ τις ἀγνοεῖ, ἀγνοεῖται</span>, “quem desconsidera [isto] é desconsiderado [por Deus]”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.38\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 14.38</a> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοείτω\" data-meanings=\"continue ignorante\">ἀγνοείτω</span>; para a justaposição de ativo/passivo, Alex. Aphr., <em>Fat.</em> 31 II/2 p. 202, 18).\n<span class=\"sense-number\">3.</span> <strong>Falhar em compreender, não compreender</strong>, com implicação de incapacidade: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ῥῆμα\" data-meanings=\"a palavra; declaração\">τὸ ῥῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.45</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν οἷς ἀγνοοῦσιν βλασφημοῦντες\" data-meanings=\"blasfemando naquilo que não compreendem\">ἐν οἷς ἀγνοοῦσιν βλασφημοῦντες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.12</a> (compare PTebt 43, 25 [118 a.C.]).\n<span class=\"sense-number\">4.</span> <strong>Não ter consciência do próprio erro, incorrer em falta/pecar involuntariamente</strong> (Isócrates, Xenofonte e outros; Polyb. 1, 67, 5; Diod S 1, 70, 7; 11, 16, 1; 17, 73, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 5.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2MA.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">2 Mc 11.31</a>; PTebt 23, 12; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγνοια\" data-meanings=\"ignorância\">ἄγνοια</span> 2 início), com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πλανᾶσθαι\" data-meanings=\"errar; desviar-se\">πλανᾶσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5.2</a> (Moffatt: “errar por ignorância”; veja o verbete seguinte e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετριοπαθέω\" data-meanings=\"tratar com moderação\">μετριοπαθέω</span>). — L. Cerfaux, RAC I 186–188. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γιγνώσκω\" data-meanings=\"conhecer\">γιγνώσκω</span> 225. M-M. TW. Sv.\n</p></section></article><article id=\"entry-agnoema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγνόημα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agnóēma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοέω\" data-meanings=\"ignorar; não saber\">ἀγνοέω</span>; desde Górgias [séc. V a.C.], 11 [<em>Helena</em>] 19; veja F. Zucker, <em>Semantica</em> ABA 38, 1963, 51 s.) <strong>Pecado cometido por ignorância/involuntariamente</strong> (Diod S 1, 71, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐλάχιστα ἀ.\" data-meanings=\"faltas mínimas\">ἐλάχιστα ἀ.</span>; 13, 90, 7; OGI 116, 2; UPZ 111, 3 [163 a.C.]; PTebt 5, 3 [118 a.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοήματα, ἁμαρτήματα, ἐνκλήματα, καταγνώσματα\" data-meanings=\"faltas por ignorância, pecados, acusações, condenações\">ἀγνοήματα, ἁμαρτήματα, ἐνκλήματα, καταγνώσματα</span> [Taubenschlag, <em>Law</em>² 430; APF 2, 1903, 483 ss.; <em>Jur. Pap.</em> nº 69; K. Latte, ARW 20, 1921, p. 287, 1]; BGU 1185, 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.13.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 13.39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 3.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.23.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 23.2</a>; JosAs 13 [p. 57, 20 Bat.] cód. A; Eus., <em>DemEv</em> 4, 10; Sófocles, <em>Oed. R.</em> é dedicado à exposição dramática do tema dessas faltas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.7</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγνοια\" data-meanings=\"ignorância\">ἄγνοια</span> 2 início; REB: “pecados inadvertidos”; NRSV: “pecados cometidos involuntariamente”). Perdoado por Deus, Hs 5, 7, 3 s. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γιγνώσκω\" data-meanings=\"conhecer\">γιγνώσκω</span> 225. M-M. TW.\n</p></section></article><article id=\"entry-agnoia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγνοια</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ágnoia⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Desde Ésquilo e Tucídides 8, 92, 11; inscrições, papiros, LXX, Test12Patr, JosAs; EpArist 130; Fílon; Jos., <em>Bell.</em> 4, 29; <em>Ant.</em> 18, 335; <em>C. Ap.</em> 1, 73; Just.; Tat. 7, 3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνοιῶν\" data-meanings=\"forma citada de ἄγνοια\">ἀγνοιῶν</span> 14, 1; Ath.; Mel., HE 4, 26, 10.)\n<span class=\"sense-number\">1.</span> Em sentido geral, <strong>falta de informação sobre algo, ignorância</strong> (Ésquilo e outros), como v.l. de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνωσία\" data-meanings=\"ignorância\">ἀγνωσία</span> = “fala ignorante”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2.15</a> P72. Mas isso pode igualmente pertencer a 2.\n<span class=\"sense-number\">2.</span> Especificamente, <strong>falta de informação que pode resultar em conduta repreensível, ignorância, inconsciência, falta de discernimento</strong> (oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συνείδησις\" data-meanings=\"consciência\">συνείδησις</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γνῶσις\" data-meanings=\"conhecimento\">γνῶσις</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπιστήμη\" data-meanings=\"conhecimento; ciência\">ἐπιστήμη</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σοφία\" data-meanings=\"sabedoria\">σοφία</span>). Em nossa literatura, de inconsciência em relação à divindade ou de faltas morais involuntárias, em oposição às deliberadas (compare Jos., <em>Ant.</em> 11, 130; Fílon, <em>Leg. All.</em> 1, 35). Compare inscrição Steinleitner 14, 3 de alguém que ignorava que o bosque onde cortara árvores era sagrado; para perspectiva do AT veja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 18.12</a> e TestGad 5:7 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετάνοια ἀναιρεῖ τὴν ἄ.\" data-meanings=\"o arrependimento remove a ignorância\">μετάνοια ἀναιρεῖ τὴν ἄ.</span>.\n<strong>a.</strong> Dos que condenaram Jesus: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κατὰ ἄγνοιαν ἐπράξατε\" data-meanings=\"agistes por ignorância\">κατὰ ἄγνοιαν ἐπράξατε</span>, “agistes sem saber o que fazíeis”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.17</a> (Polyb. 12, 12, 4; Parthenius 9, 8; Plut., <em>Mor.</em> 551e; POxy 237 VIII, 36; BGU 619, 4). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄχρι τῆς ἀγνοίας\" data-meanings=\"enquanto permanece a ignorância\">ἄχρι τῆς ἀγνοίας</span>, Hm 4, 1, 5; PtK 2 p. 14, 11; 3 p. 15, 26. — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2.15</a> P72 (veja 1 acima).\n<strong>b.</strong> Quase = <strong>pecado</strong> (assim LXX, por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 23.3</a> em paralelismo com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁμαρτίαι\" data-meanings=\"pecados\">ἁμαρτίαι</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">28.7</a>; PsSol 3:8; TestLevi 3:5; TestZeb 1:5; Fílon, <em>Ebr.</em> 154 ss.; compare Platão, <em>Tht.</em> 176c; Stoic. III p. 65, 20; Diod S 14, 1, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τ. ἰδίαν ἄγνοιαν\" data-meanings=\"a própria conduta errada\">τ. ἰδίαν ἄγνοιαν</span>; Epict. 1, 26, 6; Herm. Wr. 13, 8; 11, 21 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ τελεία κακία τὸ ἀγνοεῖν τὸ θεῖον\" data-meanings=\"a maldade completa é ignorar o divino\">ἡ τελεία κακία τὸ ἀγνοεῖν τὸ θεῖον</span>, também 10, 9; PTebt 24, 33, dos malfeitores, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λήγοντες τῆς ἀγνοίας\" data-meanings=\"cessando da ignorância\">λήγοντες τῆς ἀγνοίας</span>; Diod S 4, 11, 2: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"ignorância; delusão\">ἄ.</span> é a “delusão” que levou Héracles a cometer homicídio), IEph 19:3. Dos tempos em que as pessoas não conheciam Deus: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοὺς χρόνους τῆς ἀγνοίας\" data-meanings=\"os tempos da ignorância\">τοὺς χρόνους τῆς ἀγνοίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.30</a> (TestGad 5:7, acima). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διὰ τὴν ἄγνοιαν\" data-meanings=\"por causa da ignorância\">διὰ τὴν ἄγνοιαν</span> (Diod S 11, 10, 2; SIG 904, 6; compare Alex. Aphr., <em>Fat.</em> 19 II/2 p. 189, 16 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δι’ ἄγνοιαν ἁμαρτάνειν\" data-meanings=\"pecar por ignorância\">δι’ ἄγνοιαν ἁμαρτάνειν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.18</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῇ ἀγνοίᾳ ὑμῶν\" data-meanings=\"em vossa ignorância\">ἐν τῇ ἀγνοίᾳ ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.14</a> (alguns encontram uso gnóstico nos três textos do NT citados); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2.15</a> v.l. (por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνωσία\" data-meanings=\"ignorância\">ἀγνωσία</span>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. προτέρα\" data-meanings=\"ignorância anterior\">ἄ. προτέρα</span> Hs 5, 7, 3. O plural como v.l. por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπάταις\" data-meanings=\"enganos\">ἀπάταις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.13</a>. — L. Cerfaux, RAC I 186–188. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γιγνώσκω\" data-meanings=\"conhecer\">γιγνώσκω</span> 225. M-M. TW. Sv.\n</p></section></article><article id=\"entry-hagnos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagnós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+.) <strong>Puro, santo</strong>, termo cultual, originalmente atributo da divindade e de tudo o que lhe pertence; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar; estar em temor religioso\">ἅζομαι</span>. (Homero e outros; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. θεαὶ\" data-meanings=\"deusas puras/santas\">ἁ. θεαὶ</span> Deméter e Perséfone, IG 14, 204; SEG VIII 550, 2 [séc. I a.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"῏Ισι, ἁγνή, ἁγία\" data-meanings=\"Ísis, pura, santa\">῏Ισι, ἁγνή, ἁγία</span>; PUps 8 nº 14 [pré-cristão] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῇ Ἁγνῇ Θεᾷ\" data-meanings=\"à Deusa Pura\">τῇ Ἁγνῇ Θεᾷ</span>; veja L. Moulinier, <em>Le pur et l’impur dans la pensée des Grecs</em>, 1952.) Depois transferido para o sentido moral (Clem. Al., <em>Strom.</em> 7, 27, 2: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶς ἁ. ἐστιν ὁ μηδὲν ἑαυτῷ κακὸν συνειδώς\" data-meanings=\"é puro todo aquele que não tem consciência de mal algum em si\">πᾶς ἁ. ἐστιν ὁ μηδὲν ἑαυτῷ κακὸν συνειδώς</span>).\n<strong>a.</strong> De pessoas (Diog. L. 7, 119: segundo os estoicos os sábios são <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνοί, ὅσιοι, δίκαιοι\" data-meanings=\"puros, piedosos, justos\">ἁγνοί, ὅσιοι, δίκαιοι</span>; POxy 41, 29 s. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνοὶ πιστοὶ σύνδικοι\" data-meanings=\"procuradores puros e fiéis\">ἁγνοὶ πιστοὶ σύνδικοι</span>; Sb 4117; PHarr 55, 24, fórmula mágica), de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 3.3</a> (SibOr 3, 49 do Messias); dos apóstolos, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν ἀγνῶν ἀνδρῶν\" data-meanings=\"dos homens puros\">τῶν ἀγνῶν ἀνδρῶν</span> AcPl Ha 1, 16; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σεαυτὸν ἁ. τήρει\" data-meanings=\"conserva-te puro\">σεαυτὸν ἁ. τήρει</span>, “mantém-te puro [de pecados]”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. ἐν τῇ σαρκί\" data-meanings=\"puro na carne\">ἁ. ἐν τῇ σαρκί</span> 1 Cl 38:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. ἐν ἔργοις\" data-meanings=\"puro em obras\">ἁ. ἐν ἔργοις</span> 48:5. — <strong>Inocente</strong> (Pla., <em>Leg.</em> 6, 759c <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τοῦ φόνου\" data-meanings=\"inocente do homicídio\">ἁ. τοῦ φόνου</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συνεστήσατε ἑαυτοὺς ἁγνοὺς εἶναι\" data-meanings=\"demonstrastes ser inocentes\">συνεστήσατε ἑαυτοὺς ἁγνοὺς εἶναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 7.11</a>, onde <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῷ πράγματι\" data-meanings=\"quanto ao assunto\">τῷ πράγματι</span> deve ligar-se a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνούς\" data-meanings=\"inocentes\">ἁγνούς</span>. — Especialmente de mulheres, <strong>casta, pura</strong> (desde Ésquilo; Platão; SIG 985, 35; Sb 2481, 1 s.; PGM 36, 289): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρθένος\" data-meanings=\"virgem\">παρθένος</span> (Herodian 1, 11, 4; SIG 797, 20 [37 d.C.]; inscrição de Abércio 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 18.7</a>; Fílon, <em>Spec. Leg.</em> 1, 107) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 11.2</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2.5</a>.\n<strong>b.</strong> De coisas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅσα ἁγνά\" data-meanings=\"tudo quanto é puro\">ὅσα ἁγνά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.8</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔργα ἁ.\" data-meanings=\"obras puras\">ἔργα ἁ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 21.8</a>) Hv 3, 8, 7; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μερίς\" data-meanings=\"porção\">μερίς</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 3.9</a>) 1 Cl 30:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"χεῖρες\" data-meanings=\"mãos\">χεῖρες</span> (Eur., <em>Hipp.</em> 316 s.; <em>Or.</em> 1604) 1 Cl 29:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. ἀναστροφή\" data-meanings=\"conduta pura\">ἁ. ἀναστροφή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγωγή\" data-meanings=\"conduta\">ἀγωγή</span> 1 Cl 48:1; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συνείδησις\" data-meanings=\"consciência pura\">συνείδησις</span> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄμωμος\" data-meanings=\"irrepreensível\">ἄμωμος</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σεμνός\" data-meanings=\"digno\">σεμνός</span>) 1 Cl 1:3; Pol 5:3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάπη\" data-meanings=\"amor puro\">ἀγάπη</span> 1 Cl 21:8. Da própria pessoa (compare Herm. Wr. 1, 31 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θυσίας ἁ.\" data-meanings=\"sacrifícios puros\">θυσίας ἁ.</span>): com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμίαντον\" data-meanings=\"imaculado\">ἀμίαντον</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ βάπτισμα ἁ. τηρεῖν\" data-meanings=\"guardar puro o batismo\">τὸ βάπτισμα ἁ. τηρεῖν</span>, “manter-se puro depois do batismo”, 2 Cl 6:9; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν σάρκα ἁ. τηρεῖν\" data-meanings=\"manter a carne/corpo puro\">τὴν σάρκα ἁ. τηρεῖν</span> 8:4; 6. Da sabedoria do alto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.17</a>. — E. Williger, <em>Hagios</em> 1922. — M-M. TW. Sv.\n</p></section></article><article id=\"entry-hagnotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνότης</h1><div class=\"entry-meta\"><span class=\"greek\">ητος, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagnótēs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Pureza, sinceridade</strong> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνός\" data-meanings=\"puro\">ἁγνός</span>; Cornutus 32 p. 67, 2; IG IV, 588, 15 [séc. II d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνης ἕνεκεν καὶ ἁγνότητος\" data-meanings=\"por causa de justiça e pureza\">δικαιοσύνης ἕνεκεν καὶ ἁγνότητος</span>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἁγνότητι\" data-meanings=\"em pureza\">ἐν ἁγνότητι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 6.6</a>; em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">11.3</a> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁπλότης\" data-meanings=\"simplicidade; sinceridade\">ἁπλότης</span>) é leitura discutida, embora com atestação muito antiga. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τῆς ἀληθείας\" data-meanings=\"pureza da verdade; verdadeira pureza\">ἁ. τῆς ἀληθείας</span> Hv 3, 7, 3; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πορεύεσθαι ἐν ἁ.\" data-meanings=\"andar/viver em pureza\">πορεύεσθαι ἐν ἁ.</span> Hm 4, 4, 4. — M-M. TW.\n</p></section></article><article id=\"entry-hagnos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγνῶς</h1><div class=\"entry-meta\"><span>advérbio</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagnō̂s⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Hesíodo e outros; OGI 485, 13; 524, 6; SIG 986, 8; 16; EpArist 317; PGM 4, 2639; 12, 38 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. καὶ καθαρῶς\" data-meanings=\"pura e limpidamente\">ἁ. καὶ καθαρῶς</span>). Advérbio de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγνός\" data-meanings=\"puro\">ἁγνός</span>: <strong>puramente, sinceramente.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μένειν\" data-meanings=\"permanecer\">μένειν</span>, “permanecer em pureza”, <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 2:3\" data-tooltip-text=\"Epístola de Barnabé 2:3\">B 2:3</span>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πολιτεύεσθαι\" data-meanings=\"viver; conduzir a vida\">πολιτεύεσθαι</span>, “levar vida pura”, Hs 5, 6, 6; também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀναστρέφεσθαι\" data-meanings=\"conduzir-se; viver\">ἀναστρέφεσθαι</span> Hs 9, 27, 2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διακονεῖν\" data-meanings=\"servir\">διακονεῖν</span> “com sinceridade”, v 3, 5, 1; compare Hs 9, 26, 2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διδάσκειν σεμνῶς καὶ ἁ.\" data-meanings=\"ensinar séria e sinceramente\">διδάσκειν σεμνῶς καὶ ἁ.</span> Hs 9, 25, 2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν Χριστὸν καταγγέλλουσιν οὐχ ἁ.\" data-meanings=\"proclamam Cristo não por motivos puros\">τὸν Χριστὸν καταγγέλλουσιν οὐχ ἁ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.17</a>. — EDNT.\n</p></section></article><article id=\"entry-agnosia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγνωσία</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agnōsía⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Eurípides, Tucídides e outros; papiros, LXX; Test12Patr.) <strong>Ignorância</strong>, não predominantemente em sentido intelectual, mas, como na linguagem dos mistérios (Herm. Wr. 1, 27 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τοῦ θεοῦ\" data-meanings=\"ignorância de Deus\">ἀ. τοῦ θεοῦ</span>; 7, 1; 10, 8; <em>Kore Kosmu</em> 53 [veja H. Betz, ZTK 63, 1966, 179; 187]), <strong>falta de experiência religiosa ou de discernimento espiritual</strong> (veja Rtzst., <em>Mysterienrel.</em>³ 292 s.): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνωσίαν θεοῦ τινες ἔχουσιν\" data-meanings=\"alguns têm ignorância de Deus\">ἀγνωσίαν θεοῦ τινες ἔχουσιν</span>, “alguns não têm conhecimento de Deus” (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 13.1</a>; APF 5, 1913, 383), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 15.34</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καλεῖν ἀπὸ ἀ. εἰς ἐπίγνωσιν δόξης ὀνόματος αὐτοῦ\" data-meanings=\"chamar da ignorância ao conhecimento da glória de seu nome\">καλεῖν ἀπὸ ἀ. εἰς ἐπίγνωσιν δόξης ὀνόματος αὐτοῦ</span> 1 Cl 59:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φιμοῦν τὴν τῶν ἀφρόνων ἀνθρώπων ἀ.\" data-meanings=\"silenciar a ignorância dos homens insensatos\">φιμοῦν τὴν τῶν ἀφρόνων ἀνθρώπων ἀ.</span>, “silenciar a fala ignorante de homens insensatos”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2.15</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγνοια\" data-meanings=\"ignorância\">ἄγνοια</span> P72). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γιγνώσκω\" data-meanings=\"conhecer\">γιγνώσκω</span> 224. M-M. TW.\n</p></section></article><article id=\"entry-agnostos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγνωστος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ágnōstos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+; papiros [PGiss 3, 2 s. (117 d.C.) <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἥκω σοι, ὦ δῆμε, οὐκ ἄγνωστος Φοῖβος θεός\" data-meanings=\"venho a ti, ó povo, não como um deus Febo desconhecido\">ἥκω σοι, ὦ δῆμε, οὐκ ἄγνωστος Φοῖβος θεός</span>]; LXX; ApcSed 11, 4; Iren. 1, 20, 3; 21, 3 e outros; Fílon; Jos., <em>C. Ap.</em> 2, 167 [da <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐσία\" data-meanings=\"essência\">οὐσία</span> de Deus] e outros; Just.) <strong>Relativo àquilo que é desconhecido por falta de informação, desconhecido</strong>, na inscrição de um altar em Atenas, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνώστῳ θεῷ\" data-meanings=\"a um deus desconhecido\">ἀγνώστῳ θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.23</a> (a frase não ocorre nem na Bíblia Hebraica nem na LXX; compare Paus. 1, 1, 4: no Falero há templo de Atena e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βωμοὶ θεῶν τε ὀνομαζομένων ἀγνώστων καὶ ἡρώων\" data-meanings=\"altares de deuses chamados desconhecidos e de heróis\">βωμοὶ θεῶν τε ὀνομαζομένων ἀγνώστων καὶ ἡρώων</span>; compare 5, 14, 8 e inscrição de Pérgamo [H. Hepding, MAI 35, 1910, 454–457]). Compare também Diog. L. 1, 110: ainda se encontram entre os demos atenienses <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"βωμοὺς ἀνωνύμους\" data-meanings=\"altares sem nome\">βωμοὺς ἀνωνύμους</span>. Norden, <em>Agn. Th.</em> 1913, 115–125, pensa que a expressão vem de um discurso de Apolônio de Tiana (compare Philostrat., <em>Vi. Apoll.</em> 6, 3, 5 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγνώστων δαιμόνων βωμοὶ ἵδρυνται\" data-meanings=\"foram erigidos altares a daimones desconhecidos\">ἀγνώστων δαιμόνων βωμοὶ ἵδρυνται</span>). Sobre o problema: Clemen 290–300; R. Egger, SBWienAk 247, 3 (1965); W. Göber, Pauly-W. 2ª sér. V (1934), 1988–1994; A. Harnack, TU 39, 1 (1913), 1–46; Rtzst., NJklA 31 (1913), 146 ss.; 393 ss.; P. Corssen, ZNW 14 (1913), 309 ss.; F. Burkitt, JTS 15 (1914), 455–464; T. Birt, RhM 69 (1914), 342 ss.; O. Weinreich, “De Dis Ignotis”, ARW 18 (1915), 1–52; A. Wikenhauser, <em>D. Apostelgesch.</em> 1921, 369–394; Meyer III 1923, 96–98; Dssm., <em>Paulus</em>² 1925, 226–229 (trad. ingl. <em>Paul</em> 1926, 287–291); K. Lake, <em>Beginn.</em> I/5, 1933, 240–246; M. Dibelius, <em>Pls. auf d. Areopag</em> 1939 = cap. 2 em <em>Studies in the Acts</em>, ed. H. Greeven, 1956; B. Gärtner, <em>The Areopagus Speech and Natural Revelation</em>, 1955, 242–247; P. van der Horst, em <em>Knowledge of God in the Graeco-Roman World</em>, 1988, 19–42. Para mais bibliografia, veja s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἄρειος πάγος\" data-meanings=\"Areópago\">Ἄρειος πάγος</span>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γιγνώσκω\" data-meanings=\"conhecer\">γιγνώσκω</span> 224. M-M. TW.\n</p></section></article><article id=\"entry-agora-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγορά</h1><div class=\"entry-meta\"><span class=\"greek\">ᾶς, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agorá⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero+; inscrições, papiros, LXX; TestJob 22:3; ParJer 6:19 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν ἐθνῶν\" data-meanings=\"dos gentios\">τῶν ἐθνῶν</span>; Jos., <em>Bell.</em> 5, 513 e outros; Ath.; empréstimo no rabínico.) <strong>Praça de mercado, mercado.</strong> Como lugar para crianças brincarem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.32</a>. Lugar de pessoas procurando trabalho e de desocupados (Harpocration, s.v. Κολωνέτας: os <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μισθωτοί\" data-meanings=\"trabalhadores assalariados\">μισθωτοί</span> ficam na praça), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.3</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">23.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.46\" target=\"_blank\" rel=\"noopener noreferrer\">20.46</a>. Cenário de acontecimentos públicos, inclusive curas de Jesus: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ταῖς ἀ. ἐτίθεσαν τοὺς ἀσθενοῦντας\" data-meanings=\"punham os enfermos nas praças\">ἐν ταῖς ἀ. ἐτίθεσαν τοὺς ἀσθενοῦντας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.56</a>. Cenário de processo judicial (assim já em Homero; compare Demosth. 43, 36 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν ἀρχόντων\" data-meanings=\"dos magistrados\">τῶν ἀρχόντων</span>) contra Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.19</a>, 35 D. Da Ágora de Atenas (no Cerâmico), centro da vida pública, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.17</a> (E. Curtius, “Paulus in Athen”, SBBerlAk 1893, 925 ss.; S. Halstead, “Paul in the Agora”, <em>Quantulacumque</em> [Festschr. K. Lake], 1937, 139–143; R. Martin, <em>Recherches sur l’Agora grecque</em>, 1951). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπ’ ἀγορᾶς … ἐὰν μὴ ῥαντίσωνται οὐκ ἐσθίουσιν\" data-meanings=\"ao voltar do mercado, se não se aspergirem/lavarem, não comem\">ἀπ’ ἀγορᾶς … ἐὰν μὴ ῥαντίσωνται οὐκ ἐσθίουσιν</span> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅταν ἔλθωσιν\" data-meanings=\"quando voltam\">ὅταν ἔλθωσιν</span> [D it] é a interpretação correta) = “quando voltam do mercado, não comem sem se lavarem”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.4</a>; construção pregnante, compare <em>Vi. Aesopi</em> G 40 P.; PHolm 20, 26; Epict. 3, 19, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.34.25\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 34.25</a>. Como a forma média <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ῥαντίσωνται\" data-meanings=\"aspergir-se/lavar-se\">ῥαντίσωνται</span> diz algo sobre as pessoas que comem, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπ’ ἀγορᾶς\" data-meanings=\"do mercado\">ἀπ’ ἀγορᾶς</span> provavelmente também se refere a elas; portanto a interpretação “das coisas vendidas no mercado”, embora linguisticamente possível (Xenofonte e outros; Memnon; Appian; Polyaenus; Jos., <em>Bell.</em> 1, 308; <em>Ant.</em> 14, 472; papiros em Preis.), é insustentável. — B. 822. DELG. M-M.\n</p></section></article><article id=\"entry-agorazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγοράζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agorázō⟧</span><span class=\"separator\">·</span><span class=\"greek\">impf. ἠγόραζον; fut. ἀγοράσομεν; 1 aor. ἠγόρασα; pass. ἠγοράσθην</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<span class=\"sense-number\">1.</span> <strong>Adquirir coisas ou serviços em troca de dinheiro, comprar</strong> (transitivo desde Aristófanes; inscrições, papiros, LXX; Jos., <em>Ant.</em> 12, 175; Test12Patr), com acusativo da coisa: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἀγρὸν ἐκεῖνον\" data-meanings=\"aquele campo\">τὸν ἀγρὸν ἐκεῖνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.18</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αὐτόν\" data-meanings=\"a própria [pérola]\">αὐτόν</span> = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μαργαρίτην\" data-meanings=\"pérola\">μαργαρίτην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.46</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σινδόνα\" data-meanings=\"lençol de linho\">σινδόνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.46</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀρώματα\" data-meanings=\"aromas; especiarias\">ἀρώματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.1</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μάχαιραν\" data-meanings=\"espada\">μάχαιραν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.36</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">6.5</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν γόμον αὐτῶν\" data-meanings=\"a mercadoria deles\">τὸν γόμον αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18.11</a>. Com oração relativa como objeto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ὧν χρείαν ἔχομεν\" data-meanings=\"comprar aquilo de que necessitamos\">ἀ. ὧν χρείαν ἔχομεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13.29</a>. De campos e, figuradamente, de almas = “ganhar”, Hs 1:8 s. Com dativo de pessoa e acusativo de coisa: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἑαυτοῖς βρώματα\" data-meanings=\"alimentos para si mesmos\">ἑαυτοῖς βρώματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.15</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.36</a>; apenas dativo de pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.9</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τι εἴς τινα\" data-meanings=\"comprar algo para alguém\">ἀ. τι εἴς τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.13</a>; absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.30</a>. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πωλεῖν\" data-meanings=\"vender\">πωλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13.17</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.45\" target=\"_blank\" rel=\"noopener noreferrer\">19.45</a> v.l. Com preço no genitivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δηναρίων διακοσίων ἄρτους\" data-meanings=\"pães por duzentos denários\">δηναρίων διακοσίων ἄρτους</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.37</a>. Também com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκ\" data-meanings=\"de; com [o preço]\">ἐκ</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγόρασαν ἐξ αὐτῶν τὸν ἀγρόν\" data-meanings=\"compraram com eles o campo\">ἠγόρασαν ἐξ αὐτῶν τὸν ἀγρόν</span> (os trinta siclos), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.7</a>. O vendedor pode ser expresso por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρά τινος\" data-meanings=\"da parte de alguém\">παρά τινος</span>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. παρ’ ἐμοῦ χρυσίον\" data-meanings=\"comprar de mim ouro\">ἀ. παρ’ ἐμοῦ χρυσίον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3.18</a>.\n<span class=\"sense-number\">2.</span> <strong>Assegurar direitos sobre alguém pagando um preço, comprar, adquirir como propriedade</strong>, extensão figurada de 1, dos crentes, por quem Cristo pagou o preço com seu sangue: com genitivo de preço, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγοράσθητε τιμῆς\" data-meanings=\"fostes comprados por preço\">ἠγοράσθητε τιμῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">7.23</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τιμή\" data-meanings=\"preço; honra\">τιμή</span> 1); com pessoa em acusativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.1</a>; com dativo do possuidor e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν\" data-meanings=\"com; por meio de\">ἐν</span> do preço: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγόρασας τῷ θεῷ ἐν τῷ αἵματί σου\" data-meanings=\"compraste para Deus com teu sangue\">ἠγόρασας τῷ θεῷ ἐν τῷ αἵματί σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5.9</a>; com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπό τινος\" data-meanings=\"de alguém/de algo\">ἀπό τινος</span> indicando aquilo de que a compra separa: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγορασμένοι ἀπὸ τῆς γῆς\" data-meanings=\"comprados da terra\">ἠγορασμένοι ἀπὸ τῆς γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.3</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">4</a>. Desde Deissmann (<em>LO</em> 271–281) tornou-se comum interpretar sobretudo as afirmações paulinas à luz do direito religioso que efetivamente conferia liberdade a um escravo comprado por uma divindade (uso de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ.\" data-meanings=\"comprar\">ἀ.</span> na compra de escravo: SIG² 844, 9; OGI 338, 23; PGissUniv 20, 14 [séc. II d.C.]; POxy 1149, 5 s.; SIG 845, 1 tem <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπρίατο\" data-meanings=\"comprou\">ἐπρίατο</span> numa manumissão; veja L. Mitteis, <em>Reichsrecht u. Volksrecht</em> 1891, 374 ss.; Dssm. <em>LO</em> 275 n. 9 [<em>LAE</em> 322 ss.]). Contra a aplicação tradicional dos dados de Deissmann: W. Elert, TLZ 72, 1947, 265–270; F. Bonner, <em>Untersuchungen über die Religion der Sklaven in Griechenland und Rom</em> 1957; S. Lyonnet, <em>Biblica</em> 42, 1961, 85–89. A compra comum de escravos pode explicar a formulação do NT (compare H. Kraft, Hdb. ad loc.), mas, fossem quais fossem as intenções dos autores, imagens sacrais ocorreriam a alguns de seus públicos greco-romanos. — B. 818. DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγορά\" data-meanings=\"mercado\">ἀγορά</span>. M-M. TW. Spicq. Sv.\n</p></section></article><article id=\"entry-agoraios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγοραῖος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agoraîos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Ésquilo, Heródoto+; inscrições, papiros.) “<strong>Relativo ao mercado</strong>”; em nossa literatura apenas como substantivo.\n<span class=\"sense-number\">1.</span> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἀ.\" data-meanings=\"os homens da praça/mercado\">οἱ ἀ.</span> <strong>gente do mercado</strong>, especificamente a multidão da praça e, daí, <strong>populacho</strong> (Amônio: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγοραῖος σημαίνει τ. πονηρόν, τὸν ἐν ἀγορᾷ τεθραμμένον\" data-meanings=\"ἀγοραῖος significa o homem vil, criado na praça\">ἀγοραῖος σημαίνει τ. πονηρόν, τὸν ἐν ἀγορᾷ τεθραμμένον</span>; compare Aristoph., <em>Ran.</em> 1015; Pla., <em>Prot.</em> 347c; Theophr., <em>Char.</em> 6, 2; Dio Chrys. 49 [66], 25; Plut., <em>Aemil. Paul.</em> 38, 4 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.5</a>.\n<span class=\"sense-number\">2.</span> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱ ἀγοραῖοι\" data-meanings=\"os dias/sessões judiciais\">αἱ ἀγοραῖοι</span> (subentenda-se <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡμέραι\" data-meanings=\"dias\">ἡμέραι</span> ou <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σύνοδοι\" data-meanings=\"sessões\">σύνοδοι</span>), <strong>dias/sessões de tribunal</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. ἄγονται\" data-meanings=\"os tribunais estão em sessão\">ἀ. ἄγονται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.38</a> (Jos., <em>Ant.</em> 14, 245; EphemEpigr VII 436 nº 44, 10 [séc. II d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἀγοραῖος ἤχθη\" data-meanings=\"a sessão judicial foi realizada\">ἡ ἀγοραῖος ἤχθη</span>; Strabo 13, 4, 12 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰς ἀ. ποιεῖσθαι\" data-meanings=\"realizar as sessões judiciais\">τὰς ἀ. ποιεῖσθαι</span> = lat. <em>conventus forenses agere</em>; B-D-F §5, 3b). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγορά\" data-meanings=\"mercado\">ἀγορά</span> 12. M-M.\n</p></section></article><article id=\"entry-agra-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγρα</h1><div class=\"entry-meta\"><span class=\"greek\">ας, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ágra⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n(Homero e outros; Jos., <em>Ant.</em> 8, 40.)\n<span class=\"sense-number\">1.</span> <strong>O ato de apanhar, captura</strong> (Ctesias 688 [<em>Ind.</em> 24]: Fgm. 45g p. 494, 13 Jac.; Alciphron 1, 15, 1; Esopo, <em>Fab.</em> 21 P.//24 H.; 191 P.//260 H. = 154 III H-H.): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰς ἄ.\" data-meanings=\"para a captura; para pescar\">εἰς ἄ.</span> (Eur., <em>Suppl.</em> 885 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐς ἄγρας ἰέναι\" data-meanings=\"ir à captura\">ἐς ἄγρας ἰέναι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.4</a>; semelhantemente v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">9</a>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπὶ τῇ ἄγρᾳ τῶν ἰχθύων, ὧν συνέλαβον\" data-meanings=\"por causa da captura dos peixes que apanharam\">ἐπὶ τῇ ἄγρᾳ τῶν ἰχθύων, ὧν συνέλαβον</span>.\n<span class=\"sense-number\">2.</span> <strong>Aquilo que é apanhado, captura, pesca</strong> (Solon 23, 3 Diehl²; X., <em>Cyr.</em> 2, 4, 19; Lycophron 665; Appian, <em>Bell. Civ.</em> 4, 129 §545; Iambl. <em>Erot.</em> 34; TestZeb 6:6; POxy 3269, 1 [séc. III d.C.]): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ᾗ = ἣν συνέλαβον\" data-meanings=\"a qual = que apanharam\">ᾗ = ἣν συνέλαβον</span> v.l. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.9</a>. — DELG. <em>New Docs</em> 3, 17 s.\n</p></section></article><article id=\"entry-agrammatos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγράμματος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agrámmatos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n“<strong>Incapaz de escrever</strong>” (X., <em>Mem.</em> 4, 2, 20; Epict. 2, 2, 22; BGU 118; 152; POxy 71; 133; 134; 137; 139 e outros; E. Majer-Leonhard, <em>Ἀγράμματοι</em>, diss. Marburg 1913; R. Calderini, <em>Aeg.</em> 30, 1950, 14–41), também <strong>sem educação, iletrado</strong> (Pla., <em>Tim.</em> 23b; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνθρωποι\" data-meanings=\"homens\">ἄνθρωποι</span> em Epicuro, apud Philod., <em>Rhet.</em> 1, 141; Fílon, <em>Omn. Prob. Lib.</em> 51), de Pedro e João: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνθρωποι ἀ. καὶ ἰδιῶται\" data-meanings=\"homens sem instrução e comuns\">ἄνθρωποι ἀ. καὶ ἰδιῶται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.13</a> (W. Wuellner, <em>The Meaning of ‘Fishers of Men’</em>, 1967, 45–63: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγράμ.\" data-meanings=\"ἀγράμματος\">ἀγράμ.</span> = sem proficiência jurídica). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γράφω\" data-meanings=\"escrever\">γράφω</span>. <em>New Docs</em> 5, 12 s. M-M.\n</p></section></article><article id=\"entry-agrauleo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγραυλέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agrauléō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Viver ao ar livre</strong> (Aristóteles e outros; Plut., <em>Num.</em> 61 [4, 1]. De pastores, Bryso em Stob. 4, 28, 15; Parthenius 29, 1; compare Hom., <em>Il.</em> 18, 162 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ποιμένες ἄγραυλοι\" data-meanings=\"pastores que vivem ao ar livre\">ποιμένες ἄγραυλοι</span>; TestAbr A 10 p. 87, 23 [Stone p. 22]; ParJer), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.8</a>. — Veja DELG <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγρός\" data-meanings=\"campo\">ἀγρός</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀυλή\" data-meanings=\"pátio; curral\">ἀυλή</span>.\n</p></section></article><article id=\"entry-agreuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦agreúō⟧</span><span class=\"separator\">·</span><span class=\"greek\">1 aor. ἤγρευσα</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n“<strong>Apanhar, capturar</strong>” (Sófocles, Heródoto e outros; papiros, LXX); no NT apenas em extensão figurada, <strong>apanhar de surpresa</strong> (Sófocles, TGF Fgm. 510; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 5.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">6.25 s.</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα αὐτὸν ἀγρεύσωσιν λόγῳ\" data-meanings=\"para que o apanhassem numa palavra\">ἵνα αὐτὸν ἀγρεύσωσιν λόγῳ</span>, “para que o apanhassem numa declaração [imprudente]”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.13</a> (compare Aen. Tact. 22, 11: para que fossem o menos possível surpreendidos por forças hostis que se aproximassem furtivamente). — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγρα\" data-meanings=\"captura\">ἄγρα</span>. M-M.\n</p></section></article>"};
